#![allow(clippy::disallowed_methods)] // tests build fixture trees (DD-006)

//! The world map (REQ-MAP-001): clusters scoped to the viewer, the PMTiles
//! file served with byte ranges, glyphs and sprites confined to their
//! directory, the page under a base path and without configuration, and
//! nothing loaded from another host. The PMTiles file here is synthetic: a
//! PMTiles v3 magic followed by generated bytes, never a real extract.

mod common;

use std::sync::Arc;

use axum::body::Body;
use axum::http::{Request, StatusCode};
use http_body_util::BodyExt;
use sha2::{Digest, Sha256};
use tower::ServiceExt;

use common::*;
use lichtbild::config::{Config, MapFiles};
use lichtbild::index::Index;
use lichtbild::map::{self, Point};
use lichtbild::scan::{self, Options};
use lichtbild::web::{self, AppState};

struct Resp {
    status: StatusCode,
    headers: axum::http::HeaderMap,
    body: Vec<u8>,
}

impl Resp {
    fn text(&self) -> String {
        String::from_utf8_lossy(&self.body).into_owned()
    }
    fn header(&self, name: &str) -> Option<String> {
        self.headers
            .get(name)
            .map(|v| v.to_str().unwrap().to_string())
    }
}

async fn get(app: &axum::Router, uri: &str, range: Option<&str>) -> Resp {
    let mut req = Request::builder().uri(uri).header("host", "localhost");
    if let Some(r) = range {
        req = req.header("range", r);
    }
    let res = app
        .clone()
        .oneshot(req.body(Body::empty()).unwrap())
        .await
        .unwrap();
    let status = res.status();
    let headers = res.headers().clone();
    let body = res.into_body().collect().await.unwrap().to_bytes().to_vec();
    Resp {
        status,
        headers,
        body,
    }
}

/// The fixture plus positioned photos in both libraries, at the made-up
/// coordinates of tests/fixtures/places-cities.txt: p1 has its EXIF photo
/// near Ostdorf and one near Bergheim; p2 has two near Westdorf.
fn scanned() -> (Fixture, Config, Arc<Index>) {
    let fx = fixture();
    let w = |p: std::path::PathBuf, b: Vec<u8>| std::fs::write(p, b).unwrap();
    w(
        fx.root1.join("a/IMG_berg.jpg"),
        jpeg_with_exif(
            "2022:08:01 09:00:00",
            "+02:00",
            Some(((11, 18, 'N'), (20, 6, 'E'))),
            11,
        ),
    );
    for (i, seed) in [(1, 21u8), (2, 22)] {
        w(
            fx.root2.join(format!("IMG_west{i}.jpg")),
            jpeg_with_exif(
                &format!("2023:0{i}:02 12:00:00"),
                "+01:00",
                Some(((10, 24, 'N'), (19, 54, 'E'))),
                seed,
            ),
        );
    }
    let cfg = config(&fx, &fx.data);
    let idx = Arc::new(Index::open(&cfg.data_dir).unwrap());
    assert!(
        scan::run(&cfg, &idx, &Options::default())
            .unwrap()
            .reconciled
    );
    (fx, cfg, idx)
}

fn ids_of(idx: &Index, label: &str) -> Vec<u64> {
    let mut v: Vec<u64> = idx
        .all()
        .unwrap()
        .into_iter()
        .filter(|(_, r)| r.label == label && r.lat.is_some() && !r.missing)
        .map(|(id, _)| id)
        .collect();
    v.sort();
    v
}

/// Every item id in a clusters response, and the sum of the counts.
fn listed(json: &serde_json::Value) -> (Vec<(String, u64)>, u64) {
    let mut ids = Vec::new();
    let mut n = 0;
    for c in json["clusters"].as_array().unwrap() {
        n += c["n"].as_u64().unwrap();
        for it in c["items"].as_array().into_iter().flatten() {
            ids.push((
                it["who"].as_str().unwrap().to_string(),
                it["id"].as_u64().unwrap(),
            ));
        }
    }
    ids.sort();
    (ids, n)
}

// rivet: verifies REQ-MAP-001
// rivet: verifies REQ-AUTH-002
#[tokio::test]
async fn clusters_hold_only_the_libraries_the_viewer_may_see() {
    let (_fx, cfg, idx) = scanned();
    let p1 = ids_of(&idx, "p1");
    let p2 = ids_of(&idx, "p2");
    assert_eq!((p1.len(), p2.len()), (2, 2), "fixture positions");

    // The clustering itself, for a viewer of p1 only, at every zoom.
    let points = map::points_from(&idx).unwrap();
    assert_eq!(points.len(), 4);
    for z in 0..=20 {
        let c = map::clusters(&points, &["p1".to_string()], z, None);
        assert_eq!(c.total, 2, "z{z}");
        assert_eq!(c.clusters.iter().map(|c| c.n).sum::<usize>(), 2, "z{z}");
        for cl in &c.clusters {
            for it in &cl.items {
                assert_eq!(it.who, "p1", "z{z}: a p2 item for a p1 viewer");
                assert!(p1.contains(&it.id));
            }
        }
        // The bounds cover p1's points only (Westdorf lies further west).
        let [w, _, e, _] = c.bounds.unwrap();
        assert!(w > 20.0 && e < 20.3, "bounds {w}..{e} reach beyond p1");
    }
    assert_eq!(map::clusters(&points, &[], 10, None).total, 0);

    // Over HTTP, `who` is scoped exactly like the timeline.
    let app = web::router(AppState::new(&cfg, idx.clone()));
    for (who, want) in [("p1", &p1), ("p2", &p2)] {
        let r = get(&app, &format!("/map/clusters?z=18&who={who}"), None).await;
        assert_eq!(r.status, StatusCode::OK);
        assert_eq!(
            r.header("cache-control").as_deref(),
            Some("private, no-store")
        );
        let json: serde_json::Value = serde_json::from_slice(&r.body).unwrap();
        let (ids, n) = listed(&json);
        assert_eq!(n, 2, "{who}");
        let want: Vec<(String, u64)> = want.iter().map(|id| (who.to_string(), *id)).collect();
        assert_eq!(ids, want, "{who}");
    }
    // Operator mode sees both libraries; the merged view counts all four.
    let r = get(&app, "/map/clusters?z=18", None).await;
    let (ids, n) = listed(&serde_json::from_slice(&r.body).unwrap());
    assert_eq!((ids.len(), n), (4, 4));
    let r = get(&app, "/map/clusters?z=18&who=all", None).await;
    assert_eq!(listed(&serde_json::from_slice(&r.body).unwrap()).1, 4);
    for bad in [
        "who=nobody",
        "who=..",
        "z=300",
        "bbox=1,2,3",
        "bbox=a,b,c,d",
    ] {
        let r = get(&app, &format!("/map/clusters?{bad}"), None).await;
        assert!(r.status.is_client_error(), "{bad}: {}", r.status);
        assert!(!r.text().contains("\"id\""), "{bad} leaked items");
    }
    // The page, too, counts only what the viewer may see.
    let r = get(&app, "/map?who=p2", None).await;
    assert!(r.text().contains("2 photos and videos have a position."));
    assert_eq!(
        get(&app, "/map?who=nobody", None).await.status,
        StatusCode::NOT_FOUND
    );
}

fn pt(id: u64, label: &str, lat: f64, lon: f64) -> Point {
    let (x, y) = map::mercator(lat, lon);
    Point {
        id,
        label: Arc::from(label),
        lat,
        lon,
        x,
        y,
        taken: format!("2024-01-01T00:00:{:02}", id % 60),
        thumb: Some(format!("thumb/{id}?h=0")),
        video: false,
        est_m: 0,
    }
}

// rivet: verifies REQ-MAP-001
#[test]
fn clusters_split_with_zoom_and_follow_the_box() {
    let me = vec!["a".to_string()];
    // 20 points in a ~100 m square at made-up coordinates, 2 far away, and
    // 1 on each side of the antimeridian.
    let mut pts: Vec<Point> = (0..20)
        .map(|i| {
            pt(
                i,
                "a",
                10.52 + (i % 5) as f64 * 0.0002,
                20.27 + (i / 5) as f64 * 0.0002,
            )
        })
        .collect();
    pts.push(pt(100, "a", 11.30, 20.10));
    pts.push(pt(101, "a", 10.40, 19.90));
    pts.push(pt(102, "a", -10.0, 179.5));
    pts.push(pt(103, "a", -10.0, -179.5));

    // The whole world in one or two cells at zoom 0.
    let c = map::clusters(&pts, &me, 0, None);
    assert_eq!(c.total, 24);
    assert!(c.clusters.len() <= 3, "{:?}", c.clusters.len());
    // At zoom 8 the far points split off; the dense square stays together,
    // with its centroid inside it and no item list (more than 12).
    let c = map::clusters(&pts, &me, 8, None);
    let big = &c.clusters[0];
    assert_eq!(big.n, 20);
    assert!(big.items.is_empty());
    assert!((big.lat - 10.5204).abs() < 1e-3 && (big.lon - 20.2703).abs() < 1e-3);
    let singles: Vec<_> = c.clusters.iter().filter(|c| c.n == 1).collect();
    assert_eq!(singles.len(), 4);
    for s in singles {
        assert_eq!(s.items.len(), 1);
        assert_eq!(
            s.items[0].thumb.as_deref(),
            Some(&*format!("thumb/{}?h=0", s.items[0].id))
        );
    }
    // From the detail zoom on, a big cluster lists its newest 12 items.
    let c = map::clusters(&pts, &me, 22, None);
    assert!(c.clusters.iter().all(|c| c.n <= map::ITEMS_MAX));
    assert_eq!(c.clusters.iter().map(|c| c.n).sum::<usize>(), 24);
    let c = map::clusters(&pts, &me, map::DETAIL_ZOOM, None);
    let listed: usize = c.clusters.iter().map(|c| c.items.len()).sum();
    assert_eq!(
        listed,
        c.clusters
            .iter()
            .map(|c| c.n.min(map::ITEMS_MAX))
            .sum::<usize>()
    );

    // The box filters; total and bounds still describe everything visible.
    let b = map::parse_bbox("20.0,10.0,20.5,10.6").unwrap();
    let c = map::clusters(&pts, &me, 12, Some(b));
    assert_eq!(c.total, 24);
    assert_eq!(c.clusters.iter().map(|c| c.n).sum::<usize>(), 20);
    // A box across the antimeridian, as MapLibre gives it (east past 180).
    let b = map::parse_bbox("179.0,-11.0,181.0,-9.0").unwrap();
    let c = map::clusters(&pts, &me, 6, Some(b));
    assert_eq!(c.clusters.iter().map(|c| c.n).sum::<usize>(), 2);
    // A box wider than the world holds every longitude.
    let b = map::parse_bbox("-300,-80,300,80").unwrap();
    assert_eq!(
        map::clusters(&pts, &me, 1, Some(b))
            .clusters
            .iter()
            .map(|c| c.n)
            .sum::<usize>(),
        24
    );
    for bad in [
        "",
        "1,2,3",
        "1,2,3,4,5",
        "a,b,c,d",
        "1,5,2,4",
        "NaN,0,1,1",
        "inf,0,1,1",
    ] {
        assert!(map::parse_bbox(bad).is_none(), "{bad:?}");
    }
    // Another label's points are never part of it.
    pts.push(pt(200, "b", 10.52, 20.27));
    let c = map::clusters(&pts, &me, 22, None);
    assert_eq!(c.total, 24);
    assert!(c
        .clusters
        .iter()
        .all(|c| c.items.iter().all(|i| i.id != 200)));
}

/// A synthetic PMTiles file: the v3 magic and `len - 8` generated bytes.
fn synthetic_pmtiles(len: usize) -> Vec<u8> {
    let mut b = b"PMTiles\x03".to_vec();
    b.extend((8..len).map(|i| (i * 31 % 251) as u8));
    b
}

struct MapFixture {
    _tmp: tempfile::TempDir,
    pmtiles: Vec<u8>,
    files: MapFiles,
    outside: std::path::PathBuf,
}

/// A PMTiles file, an assets directory with one glyph range and one sprite,
/// a secret next to it, and a symlink from inside the directory to it.
fn map_files() -> MapFixture {
    let tmp = tempfile::tempdir().unwrap();
    let base = tmp.path().canonicalize().unwrap();
    let pm = synthetic_pmtiles(40_000);
    std::fs::write(base.join("world.pmtiles"), &pm).unwrap();
    let assets = base.join("assets");
    std::fs::create_dir_all(assets.join("fonts/Noto Sans Regular")).unwrap();
    std::fs::create_dir_all(assets.join("sprites/v4")).unwrap();
    std::fs::write(assets.join("fonts/Noto Sans Regular/0-255.pbf"), b"glyphs").unwrap();
    std::fs::write(assets.join("sprites/v4/light.json"), b"{}").unwrap();
    let outside = base.join("secret.pbf");
    std::fs::write(&outside, b"secret").unwrap();
    std::os::unix::fs::symlink(&outside, assets.join("fonts/link.pbf")).unwrap();
    let files = map::check_files(&MapFiles {
        pmtiles: Some(base.join("world.pmtiles")),
        assets: Some(assets),
    })
    .unwrap();
    MapFixture {
        _tmp: tmp,
        pmtiles: pm,
        files,
        outside,
    }
}

// rivet: verifies REQ-MAP-001
#[tokio::test]
async fn the_pmtiles_file_is_served_with_byte_ranges() {
    let (_fx, mut cfg, idx) = scanned();
    let mf = map_files();
    cfg.map = mf.files.clone();
    let app = web::router(AppState::new(&cfg, idx.clone()));
    let len = mf.pmtiles.len();

    // pmtiles.js reads the header first: bytes 0-16383.
    let r = get(&app, "/map/tiles.pmtiles", Some("bytes=0-16383")).await;
    assert_eq!(r.status, StatusCode::PARTIAL_CONTENT);
    assert_eq!(r.body, mf.pmtiles[..16384]);
    assert_eq!(
        r.header("content-range").unwrap(),
        format!("bytes 0-16383/{len}")
    );
    assert_eq!(r.header("content-length").unwrap(), "16384");
    assert_eq!(r.header("accept-ranges").unwrap(), "bytes");
    assert_eq!(r.header("content-type").unwrap(), "application/vnd.pmtiles");
    let etag = r.header("etag").expect("an ETag for pmtiles.js");
    assert!(etag.starts_with('"') && !etag.starts_with("W/"), "{etag}");
    // A range in the middle, the tail, and the whole file.
    let r = get(&app, "/map/tiles.pmtiles", Some("bytes=20000-20099")).await;
    assert_eq!(r.status, StatusCode::PARTIAL_CONTENT);
    assert_eq!(r.body, mf.pmtiles[20000..20100]);
    let r = get(&app, "/map/tiles.pmtiles", Some("bytes=-10")).await;
    assert_eq!(r.body, mf.pmtiles[len - 10..]);
    let r = get(&app, "/map/tiles.pmtiles", None).await;
    assert_eq!(r.status, StatusCode::OK);
    assert_eq!(r.body, mf.pmtiles);
    assert_eq!(r.header("etag"), Some(etag));
    // Past the end: 416 with the length, as pmtiles.js expects.
    let r = get(&app, "/map/tiles.pmtiles", Some(&format!("bytes={len}-"))).await;
    assert_eq!(r.status, StatusCode::RANGE_NOT_SATISFIABLE);
    assert_eq!(r.header("content-range").unwrap(), format!("bytes */{len}"));
    assert!(r.body.is_empty());
    // Every map response carries the same-origin CSP.
    assert_eq!(
        r.header("content-security-policy").as_deref(),
        Some(web::CSP)
    );
    // Only that file: nothing next to it is reachable through the route.
    for uri in [
        "/map/tiles.pmtiles/..%2Fsecret.pbf",
        "/map/secret.pbf",
        "/map/tiles.pmtiles%2F..%2Fsecret.pbf",
    ] {
        let r = get(&app, uri, None).await;
        assert_ne!(r.status, StatusCode::OK, "{uri}");
        assert!(!r.text().contains("secret"), "{uri}");
    }
}

// rivet: verifies REQ-MAP-001
#[tokio::test]
async fn glyphs_and_sprites_are_confined_to_their_directory() {
    let (_fx, mut cfg, idx) = scanned();
    let mf = map_files();
    cfg.map = mf.files.clone();
    let app = web::router(AppState::new(&cfg, idx.clone()));
    let r = get(
        &app,
        "/map/assets/fonts/Noto%20Sans%20Regular/0-255.pbf",
        None,
    )
    .await;
    assert_eq!(r.status, StatusCode::OK);
    assert_eq!(r.body, b"glyphs");
    assert_eq!(r.header("content-type").unwrap(), "application/x-protobuf");
    let r = get(&app, "/map/assets/sprites/v4/light.json", None).await;
    assert_eq!((r.status, r.body.as_slice()), (StatusCode::OK, &b"{}"[..]));
    assert!(mf.outside.exists());
    for uri in [
        "/map/assets/..%2Fsecret.pbf",
        "/map/assets/fonts/..%2F..%2Fsecret.pbf",
        "/map/assets/fonts/../../secret.pbf",
        "/map/assets/%2Fetc%2Fhosts.json",
        "/map/assets/fonts/link.pbf",
        "/map/assets/secret.pbf",
        "/map/assets/fonts/Noto%20Sans%20Regular/0-255.txt",
        "/map/assets/fonts/Noto%20Sans%20Regular",
    ] {
        let r = get(&app, uri, None).await;
        assert_ne!(r.status, StatusCode::OK, "{uri}");
        assert!(!r.text().contains("secret"), "{uri} served the secret");
    }
    // The request path is checked before the file system is touched.
    assert!(map::asset_path("fonts/a/0-255.pbf").is_some());
    for bad in [
        "../fonts/a.pbf",
        "/fonts/a.pbf",
        "fonts/../../a.pbf",
        "x/a.pbf",
        "fonts/a.js",
    ] {
        assert!(map::asset_path(bad).is_none(), "{bad}");
    }
    // Configuration checks: absolute, existing, a PMTiles v3 file, a dir.
    let not_pm = mf.outside.clone();
    for bad in [
        MapFiles {
            pmtiles: Some("rel.pmtiles".into()),
            assets: None,
        },
        MapFiles {
            pmtiles: Some(not_pm.clone()),
            assets: None,
        },
        MapFiles {
            pmtiles: Some(not_pm.with_file_name("none.pmtiles")),
            assets: None,
        },
        MapFiles {
            pmtiles: None,
            assets: Some(not_pm.clone()),
        },
        MapFiles {
            pmtiles: None,
            assets: Some("rel".into()),
        },
    ] {
        assert!(map::check_files(&bad).is_err(), "{bad:?}");
    }
}

// rivet: verifies REQ-MAP-001
#[tokio::test]
async fn without_a_map_file_the_page_says_so_and_clusters_still_work() {
    let (_fx, cfg, idx) = scanned();
    assert_eq!(cfg.map, MapFiles::default());
    let app = web::router(AppState::new(&cfg, idx.clone()));
    let r = get(&app, "/map", None).await;
    assert_eq!(r.status, StatusCode::OK);
    let html = r.text();
    assert!(html.contains("No map file configured"), "{html}");
    assert!(html.contains("4 photos and videos have a position."));
    assert!(!html.contains("maplibre"), "map scripts without a map file");
    assert!(!html.contains("id=\"map\""));
    let r = get(&app, "/map/clusters?z=3", None).await;
    assert_eq!(r.status, StatusCode::OK);
    assert_eq!(listed(&serde_json::from_slice(&r.body).unwrap()).1, 4);
    for uri in ["/map/tiles.pmtiles", "/map/assets/fonts/a/0-255.pbf"] {
        assert_eq!(
            get(&app, uri, None).await.status,
            StatusCode::NOT_FOUND,
            "{uri}"
        );
    }
    // With the PMTiles file but no assets: a map without labels or icons.
    let mut cfg2 = cfg.clone();
    let mf = map_files();
    cfg2.map = MapFiles {
        pmtiles: mf.files.pmtiles.clone(),
        assets: None,
    };
    let app = web::router(AppState::new(&cfg2, idx.clone()));
    let html = get(&app, "/map", None).await.text();
    assert!(
        html.contains(r#"data-pmtiles="map/tiles.pmtiles""#),
        "{html}"
    );
    assert!(!html.contains("data-glyphs") && !html.contains("data-sprite"));
    // With both: glyphs and sprites are offered.
    cfg2.map = mf.files.clone();
    let html = get(&web::router(AppState::new(&cfg2, idx)), "/map", None)
        .await
        .text();
    assert!(html.contains(r#"data-glyphs="map/assets/fonts/""#));
    assert!(html.contains(r#"data-sprite="map/assets/sprites/v4/""#));
}

// rivet: verifies REQ-MAP-001
// rivet: verifies REQ-WEB-002
#[tokio::test]
async fn the_map_works_under_the_base_path() {
    let (_fx, mut cfg, idx) = scanned();
    let mf = map_files();
    cfg.map = mf.files.clone();
    cfg.base_path = "/photos".into();
    let app = web::router(AppState::new(&cfg, idx.clone()));
    let r = get(&app, "/photos/map", None).await;
    assert_eq!(r.status, StatusCode::OK);
    let html = r.text();
    assert!(html.contains(r#"<base href="/photos/">"#));
    let rest = html.replace(r#"<base href="/photos/">"#, "");
    for abs in [
        "href=\"/",
        "src=\"/",
        "data-pmtiles=\"/",
        "data-worker=\"/",
        "data-glyphs=\"/",
    ] {
        assert!(!rest.contains(abs), "{abs} bypasses the base path: {html}");
    }
    // Every page links the map in its header, relative to the base.
    for uri in ["/photos/", "/photos/t/p1", "/photos/map"] {
        let page = get(&app, uri, None).await.text();
        let header = page
            .split("<header>")
            .nth(1)
            .unwrap()
            .split("</header>")
            .next()
            .unwrap();
        assert!(
            header.contains(r#"<a href="map"><b>Map</b>"#),
            "{uri}: {header}"
        );
    }
    let scripts: Vec<String> = html
        .split("src=\"")
        .skip(1)
        .map(|s| s.split('"').next().unwrap().to_string())
        .collect();
    assert!(scripts.len() >= 5, "{scripts:?}");
    let extra = [
        "static/maplibre-gl-5.24.1.css".to_string(),
        "static/maplibre-gl-csp-worker-5.24.1.js".to_string(),
    ];
    for s in scripts.iter().chain(extra.iter()) {
        assert_eq!(
            get(&app, &format!("/photos/{s}"), None).await.status,
            StatusCode::OK,
            "{s}"
        );
    }
    let r = get(&app, "/photos/map/tiles.pmtiles", Some("bytes=0-99")).await;
    assert_eq!(r.status, StatusCode::PARTIAL_CONTENT);
    assert_eq!(r.body, mf.pmtiles[..100]);
    assert_eq!(
        get(&app, "/photos/map/clusters?z=2", None).await.status,
        StatusCode::OK
    );
    assert_eq!(
        get(&app, "/photos/map/assets/sprites/v4/light.json", None)
            .await
            .status,
        StatusCode::OK
    );
    for uri in ["/map", "/map/tiles.pmtiles", "/map/clusters"] {
        assert_eq!(
            get(&app, uri, None).await.status,
            StatusCode::NOT_FOUND,
            "{uri}"
        );
    }
}

/// Hosts named in a vendored file that the browser never contacts, with the
/// reason. A new host in an updated library fails the test until it is
/// looked at and added here.
const VENDORED_HOSTS: &[(&str, &str, &str)] = &[
    (
        "maplibre-gl-csp-5.24.1.js",
        "www.w3.org",
        "XML namespaces of created SVG and XHTML elements",
    ),
    (
        "maplibre-gl-csp-5.24.1.js",
        "github.com",
        "licence URL in the header comment",
    ),
    (
        "maplibre-gl-csp-5.24.1.js",
        "maplibre.invalid",
        "base for URL parsing in the attribution sanitiser; .invalid never resolves",
    ),
    (
        "maplibre-gl-csp-5.24.1.js",
        "maplibre.org",
        "link in the default attribution and logo; map.js sets its own attribution and no logo",
    ),
    (
        "maplibre-gl-csp-worker-5.24.1.js",
        "github.com",
        "licence comment and an issue link in a warning text",
    ),
    (
        "maplibre-gl-5.24.1.css",
        "www.w3.org",
        "SVG namespace inside data: icons that lichtbild.css overrides",
    ),
    (
        "pmtiles-4.5.0.js",
        "github.com",
        "documentation link in an error message of the unused Leaflet layer",
    ),
];

fn host_of(url: &str) -> String {
    url.split("//")
        .nth(1)
        .unwrap_or("")
        .chars()
        .take_while(|c| c.is_ascii_alphanumeric() || *c == '.' || *c == '-')
        .collect()
}

// rivet: verifies REQ-MAP-001
// rivet: verifies REQ-WEB-003
#[tokio::test]
async fn the_map_loads_nothing_from_another_host() {
    let (fx, mut cfg, idx) = scanned();
    let mf = map_files();
    cfg.map = mf.files.clone();
    let app = web::router(AppState::new(&cfg, idx.clone()));
    let mut texts = Vec::new();
    for uri in [
        "/map",
        "/map?who=p1",
        "/map/clusters?z=18",
        "/map/assets/sprites/v4/light.json",
        "/static/map.js",
    ] {
        let r = get(&app, uri, None).await;
        assert_eq!(r.status, StatusCode::OK, "{uri}");
        assert_eq!(
            r.header("content-security-policy").as_deref(),
            Some(web::CSP),
            "{uri}"
        );
        texts.push((uri.to_string(), r.text()));
    }
    let r = get(&app, "/map/tiles.pmtiles", Some("bytes=0-9")).await;
    assert_eq!(
        r.header("content-security-policy").as_deref(),
        Some(web::CSP)
    );
    let unconfigured = web::router(AppState::new(&config(&fx, &fx.data), idx.clone()));
    texts.push((
        "/map (no file)".into(),
        get(&unconfigured, "/map", None).await.text(),
    ));
    for (uri, text) in &texts {
        let urls = outside_urls(text);
        assert!(urls.is_empty(), "{uri} references {urls:?}");
        if uri.starts_with("/map") && !uri.contains("clusters") && !uri.contains("assets") {
            assert!(
                !text.contains(" style="),
                "{uri} has an inline style attribute"
            );
            assert!(
                !text.contains("<style"),
                "{uri} has an inline style element"
            );
            for tag in text.split("<script").skip(1) {
                assert!(
                    tag.trim_start().starts_with("src="),
                    "{uri} has an inline script"
                );
            }
        }
    }
    // The map page's scripts and styles are lichtbild's own files.
    let html = &texts[0].1;
    assert!(html.contains(r#"<script src="static/maplibre-gl-csp-5.24.1.js" defer>"#));
    assert!(html.contains(r#"data-worker="static/maplibre-gl-csp-worker-5.24.1.js""#));
    // The vendored libraries name other hosts only where the browser never
    // contacts them (comments, namespaces, replaced defaults).
    for (name, body) in map::vendored() {
        let r = get(&app, &format!("/static/{name}"), None).await;
        assert_eq!(r.status, StatusCode::OK, "{name}");
        assert_eq!(r.body, body.as_bytes(), "{name}");
        assert_eq!(
            r.header("content-security-policy").as_deref(),
            Some(web::CSP)
        );
        for url in outside_urls(body) {
            let host = host_of(&url);
            let known = VENDORED_HOSTS
                .iter()
                .any(|(f, h, _)| *f == name && *h == host);
            assert!(known, "{name} names {url:?}, host {host:?} is not reviewed");
        }
        // No blob: worker and no eval: the CSP needs neither.
        if name.contains("csp") {
            assert!(!body.contains("new Function("), "{name}");
        }
    }
    // map.js gives MapLibre its own attribution (the default links out).
    assert!(map::MAP_JS.contains("attributionControl: { compact: false }"));
    assert!(map::MAP_JS.contains("© OpenStreetMap"));
    // The CSP still names no source other than 'self' and 'none'.
    for directive in web::CSP.split(';') {
        for src in directive.split_whitespace().skip(1) {
            assert!(src == "'self'" || src == "'none'", "CSP allows {src}");
        }
    }
}

