// rivet: verifies REQ-MAP-001
#[test]
fn vendored_map_assets_match_their_pinned_sha256() {
    let notice = include_str!("../assets/VENDORED.md");
    let vendored = map::vendored();
    assert_eq!(vendored.len(), PINNED.len());
    for (name, body) in vendored {
        let want = PINNED
            .iter()
            .find(|(n, _)| *n == name)
            .unwrap_or_else(|| panic!("{name} has no pinned sha256"))
            .1;
        let got = format!("{:x}", Sha256::digest(body.as_bytes()));
        assert_eq!(got, want, "{name} differs from the pinned upstream file");
        assert!(
            notice.contains(want),
            "assets/VENDORED.md lacks the sha256 of {name}"
        );
    }
}
